-- Reviewed batch 13 for 2027 (language schools). Applied to the configured Supabase project on 2026-11-03.
-- Sources and limitations: docs/REDESIGN-AND-DATA.md and data/school-reviews.ts.
-- Twenty legacy candidates were examined. This transaction includes only eleven verified entities.
-- Controlled sync: explicit inserts for records verified absent remotely; no DELETE, bulk import, or schema changes.
BEGIN;
DO $$ BEGIN
  IF (SELECT count(*) FROM "LanguageSchool" WHERE slug IN ('yokohama-design', 'kyoto-genki', 'osaka-ecc', 'nagoya-international', 'nagoya-jls', 'shizuoka-slis', 'fukuoka-jls', 'fukuoka-gaigo', 'kumamoto-gaigo', 'nagano-jls', 'nishinihon')) <> 0 THEN
    RAISE EXCEPTION 'One or more reviewed records already exist; no inserts applied';
  END IF;
END $$;
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'yokohama-design', '横滨设计学院', '横浜デザイン学院', '神奈川县横滨市西区中央1-33-6', '日本语学科长期预备课程现行费用：1年895,000、1年6月1,259,000、2年1,623,000日元；该表自2024年4月起适用，2027金额须以校方要项确认。', '官网现行要项允许分期缴费；具体期数与条件以申请时附表为准。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '日本语学科长期预备课程为1年、1年6月或2年', '具体申请资格、材料与日语条件以当期日本语学科募集要项为准，不以统一N5替代。', '设计专门课为独立课程；本批未确认日本语学科学生的自动衔接或保证入学。', '长期课程的入学期以校方当期要项为准。', '这里是独立的日本语学科长期预备课程，不是“日语加设计”捆绑课程；后续设计专门课须按其单独要项申请。', 'https://www.ydc.ac.jp/jpn/', '["独立日本语学科","N5至N1分级学习","另设设计专门课程","现行费用可分期"]'::jsonb, '[{"name":"日本语学科长期预备课程","description":"面向N5至N1阶段的日语学习者，提供1年、1年6月或2年课程。"},{"name":"设计专门课程（另行申请）","description":"学院同时设有专门课，但不与日本语学科自动合并或保证衔接。"}]'::jsonb, '{"enrollmentFee":"选考料25,000日元、入学金100,000日元","annualTuition":"1年授课费650,000日元","materialsFee":"设施费30,000日元（1年课程）","totalFirstYear":"1年课程895,000日元（官网现行表）","otherFees":"1年6月、2年课程的设施等费用依官网附表；教材等另以校方当期说明为准"}'::jsonb, '["计划横滨长期日语学习","希望之后另行申请设计专门课程","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'kyoto-genki', 'GenkiJACS京都校', 'GenkiJACS 京都校', '京都府京都市下京区山王町569 金和大楼', '官网按周数、课程与住宿方案定价；本批未将第三方的2027报价或旧的“约91万/年”写入。', '依官网课程预订条款与费用表确认。', '本批未核实。', '可按周数选读的现场日语课程', '官网未将京都校表述为提供留学签证担保的2年进学日语学校；签证适用性须向校方确认。', '不适用。', '课程可按官网可用日期预约。', '原条目的“GENKO留学签1—2年学校”无法核实；已更正为官网可确认的GenkiJACS京都校，并移除虚构的升学、签证与费用承诺。', 'https://www.genkijacs.com/kyoto-school-intro.php', '["短期/弹性周数课程","京都市中心","核心日语课程","可选文化类模块"]'::jsonb, '[{"name":"Core Japanese Course","description":"以日常沟通能力为目标的日语课程；具体周数和开课日期以官网为准。"}]'::jsonb, '{"enrollmentFee":"申请与教材相关费用以官网实时费用表为准","annualTuition":"按学习周数与课程组合计费，不适用虚构的年度统一学费","materialsFee":"以课程费用表为准","totalFirstYear":"不适用：该校官网主打可自选周数的短期/长期现场课程"}'::jsonb, '["希望京都短期或弹性日语课程","不依赖该校办理留学签","可按官网实时价格预订"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'osaka-ecc', 'ECC国际外语专门学校', 'ECC国際外語専門学校', '大阪府大阪市北区中崎西1-5-11（2号馆）', '日本语学科2027招生要项已发布；本批保留其为专门学校内的日本语学科，不再以无来源的“约95万/年”概括，具体金额以2027要项为准。', '依2027日本语学科募集要项确认。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '长课与短课并设，具体年限以2027日本语学科要项为准', '申请资格与签证材料以日本语学科2027要项为准，不以统一N5替代。', '不适用。', '长课/短课的入学期以2027要项为准。', '此条为ECC国际外语专门学校的日本语学科，不是普通语言学校模板；官网正在为2027年度认定日本语教育机构运营做准备。', 'https://japan.ecc.ac.jp/admission/download/', '["专门学校内的日本语学科","2027招生要项已发布","长课与短课","大阪梅田区域"]'::jsonb, '[{"name":"日本语学科长课","description":"面向留学与长期学习者；条件、年限及费用以2027要项为准。"},{"name":"日本语学科短课","description":"短期学习安排依官网当期说明。"}]'::jsonb, '{"enrollmentFee":"以2027日本语学科募集要项为准","annualTuition":"以2027日本语学科募集要项为准","materialsFee":"以2027日本语学科募集要项为准","totalFirstYear":"以2027日本语学科募集要项为准"}'::jsonb, '["希望大阪日本语学科学习","能按2027要项确认费用与资格","需要区分日语学科与该校其他专门课程"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'nagoya-international', '名古屋国际日本语学校', '名古屋国際日本語学校', '爱知县名古屋市中区丸之内2-6-4', '官网当前升学课程首年747,000日元（选考22,000、入学88,000、授课594,000、社会学习12,000、保险及医疗10,000、教材21,000）；公开页未标为2027费用。', '选考料在出愿时支付，余款按COE等流程以校方通知为准。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '升学课程设2年及按入学期缩短的课程', '申请资格和日语要求以官网当期升学课程要项为准。', '本批未核实。', '以官网当期升学课程募集说明为准。', '已纠正为官网学校全称；不再把中部制造业就业、半年付款或统一语言门槛写成已核实事实。', 'https://nagoyais.com/application-advancement-course/', '["升学课程","名古屋市中区","当前首年费用已公开","费用含教材与保险医疗项目"]'::jsonb, '[{"name":"升学课程","description":"面向升入日本高等教育机构的日语学习；课程年限与申请条件按当期要项确认。"}]'::jsonb, '{"enrollmentFee":"入学金88,000日元（另有选考料22,000日元）","annualTuition":"授课费594,000日元","materialsFee":"教材21,000日元","totalFirstYear":"747,000日元（官网当前升学课程）","otherFees":"社会学习12,000、保险及医疗10,000日元；2027金额待校方确认"}'::jsonb, '["计划名古屋升学日语课程","需要查看公开首年费用构成","能以申请时要项确认2027价格"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'nagoya-jls', 'NSA日本语学校', 'NSA日本語学校', '爱知县名古屋市千种区萱场1-6-7', '学校官网公开募集要项，但本批未取得可核对的2027费用表；已删除旧的“80万日元/年”与性价比排名说法。', '本批未核实。', '本批未核实。', '以官网当期募集要项为准', '以官网当期募集要项为准。', '本批未核实。', '以官网当期募集要项为准。', '原条目名称无法与地址对应；已按官网及所在地更正为NSA日本语学校，费用和课程条件保持待校方公布。', 'https://japan-nsa.jp/', '["名古屋市千种区","官网公开募集要项","已移除无来源价格与排名"]'::jsonb, '[{"name":"日语课程","description":"具体课程结构、年限及招生条件以官网最新募集要项为准。"}]'::jsonb, '{"enrollmentFee":"2027费用待校方公布","annualTuition":"2027费用待校方公布","materialsFee":"2027费用待校方公布","totalFirstYear":"2027费用待校方公布"}'::jsonb, '["计划名古屋学习日语","愿意直接向校方确认2027课程和费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'shizuoka-slis', '静冈国际语言学院', '静岡国際言語学院', '静冈县袋井市', '官网当前进学2年课程首年1,246,000日元（选考120,000、首年学费1,086,000、入学金40,000）；教材费不含，公开页未标为2027费用。', '以官网入学案内与当期通知为准。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '进学2年课程（4月）或一般2年课程（10月）', '申请人原则上应在入学时高中或大学毕业不超过约4年，并按校方要求提交学习理由等材料。', '本批未核实。', '进学2年课程4月；一般2年课程10月。', '已纠正校名及所在地；官网费用并非旧条目的78万日元，且未将现行费用伪作2027定价。', 'https://sils-japanese.com/course-fee/', '["学校法人","袋井市","进学与一般两类2年课程","EJU/JLPT对策"]'::jsonb, '[{"name":"进学2年课程","description":"4月入学，面向大学或专门学校升学，并提供EJU/JLPT对策。"},{"name":"一般2年课程","description":"10月入学，学习日语并获得升学或就业支持。"}]'::jsonb, '{"enrollmentFee":"入学金40,000日元（另有选考料120,000日元）","annualTuition":"首年学费1,086,000日元","materialsFee":"教科书与教材费不含在学费内","totalFirstYear":"1,246,000日元（官网当前进学2年课程）","otherFees":"第二年及一般2年课程费用以官网表为准；2027金额待校方确认"}'::jsonb, '["计划静冈西部2年日语课程","需要升学或就业支持","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'fukuoka-jls', '福冈日本语学校', '福岡日本語学校', '福冈县福冈市南区清水2-13-5', '官网2026年修订费用表：2年1,555,000、1年9月1,390,000、1年6月1,223,000、1年3月1,058,000日元；公开表未标为2027费用。', '依官网费用表分期节点缴纳；具体2027安排待校方确认。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '2年、1年9月、1年6月或1年3月', '以官网当期申请资料为准。', '本批未核实。', '4月/7月/10月/1月。', '已更正校址（并非博多站步行圈），并移除“九州大学目标班”等无来源主张；现行费用表不被冒充为2027报价。', 'https://www.fukuokaschool.com/fjls/profile/', '["福冈市南区清水","四季入学","2年至1年3月课程","公开现行费用表"]'::jsonb, '[{"name":"留学签日语课程","description":"按4/7/10/1月入学期设置2年至1年3月学习期。"}]'::jsonb, '{"enrollmentFee":"入学金66,000日元（另有选考料30,000日元）","annualTuition":"授课费660,000日元","materialsFee":"其他费用109,000日元（项目以费用表为准）","totalFirstYear":"2年、1年9月与1年6月课程首缴865,000日元；1年3月课程先缴865,000日元后再缴193,000日元","otherFees":"全程合计依入学期不同；上述为2026修订费用表，非2027承诺"}'::jsonb, '["计划福冈长期日语课程","需要四季入学","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'fukuoka-gaigo', '福冈国际外语学院', '福岡国際外語学院', '福冈县（具体校址以官网当期案内为准）', '官网当前费用表的首年示例为987,700日元，含选考30,000、入学50,000、年授课600,000、教材60,000、设施50,000、体检10,000、保险10,000及首6个月双人宿舍等；页面未标为2027费用。', '依官网当期缴费安排确认。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '以官网当期课程案内为准', '以官网当期申请条件为准。', '本批未核实。', '以官网当期课程案内为准。', '已将旧的“福冈外语学院”更正为官网学校全称；不再把未核实的推荐入学、就职方向或统一语言门槛写作事实。', 'https://fukuoka-ifls.com/overview/', '["福冈国际外语学院","首年费用示例含宿舍项目","当前费用未标2027"]'::jsonb, '[{"name":"日语课程","description":"课程年限、入学期与申请资格以官网当期案内为准。"}]'::jsonb, '{"enrollmentFee":"入学金50,000日元（另有选考料30,000日元）","annualTuition":"授课费600,000日元/年","materialsFee":"教材60,000日元/年","totalFirstYear":"987,700日元（官网示例，含首6个月双人宿舍与寝具等）","otherFees":"设施50,000、体检10,000、保险10,000、宿舍入寮20,000及6个月双人宿舍150,000等；2027金额待确认"}'::jsonb, '["计划福冈学习日语","需要把宿舍费用与学费分开核算","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'kumamoto-gaigo', '熊本外语专门学校日本语科', '熊本外語専門学校 日本語科', '熊本县熊本市中央区辛岛町8-14', '2027日本语科资料显示：2年课程首年865,000日元、1年6月课程首年830,000日元；其他年次与明细以2027募集要项为准。', '可分期支付的条件以校方FAQ及2027募集要项为准。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '进学2年课程或1年6月课程', '以2027日本语科募集要项为准。', '不适用。', '课程入学期以2027募集要项为准。', '已纠正为熊本外语专门学校的日本语科；删除虚构的IT就业课程和统一N5/出勤率断言。', 'https://www.kfla-nihongo.com/course-nihongo/', '["专门学校内的日本语科","2年与1年6月进学课程","2027首年费用已公开","熊本市中央区"]'::jsonb, '[{"name":"进学2年课程","description":"面向升入日本大学或专门学校的留学生。"},{"name":"进学1年6月课程","description":"面向升学准备的留学生；具体条件以2027要项为准。"}]'::jsonb, '{"enrollmentFee":"以2027日本语科募集要项为准","annualTuition":"2年课程首年总额865,000日元；1年6月课程首年830,000日元","materialsFee":"以2027募集要项明细为准","totalFirstYear":"2年865,000日元；1年6月830,000日元"}'::jsonb, '["计划熊本升学日语课程","需要2年或1年6月课程","能按2027要项确认明细"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'nagano-jls', '长野21日本语学院', '長野21日本語学院', '长野县长野市川中岛町原1318', '官网当前全课程首年674,000日元（选考20,000、入学50,000、授课588,000、设施/教材等36,000）；公开页未标为2027费用。', 'COE获批后在签证申请前缴纳首年费用；续费在更新在留期限时缴纳。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '进学2年、进学1年9月或进学1年6月', '须完成12年教育、具JLPT4级相当与150小时以上可证明日语学习经历，并具备留学所需经济能力。', '本批未核实。', '4月（2年）、7月（1年9月）、10月（1年6月）。', '原条目名称已更正为长野21日本语学院；移除旅游就业和冬季运动等无来源营销内容。', 'https://www.nagano21jp.com/admission-guidelines/', '["长野市川中岛","三种进学课程","150小时日语学习经历","当前首年费用已公开"]'::jsonb, '[{"name":"进学2年课程","description":"4月入学，学习至第二年3月。"},{"name":"进学1年9月/1年6月课程","description":"分别于7月/10月入学，学习至次年或第二年3月。"}]'::jsonb, '{"enrollmentFee":"入学金50,000日元（另有选考料20,000日元）","annualTuition":"授课费588,000日元","materialsFee":"设施/教材等36,000日元","totalFirstYear":"674,000日元（官网当前表）","otherFees":"第二年金额依课程剩余年限为312,000/468,000/624,000日元；2027金额待校方确认"}'::jsonb, '["计划长野升学日语课程","已有可证明的150小时日语学习经历","能以申请时要项确认2027费用"]'::jsonb
);
